/* NutriPath — local records with optional authenticated account synchronisation. */
(async()=>{'use strict';
const MEALS=['breakfast','lunch','dinner','snack'];const MEAL_LABEL={breakfast:'朝食',lunch:'昼食',dinner:'夕食',snack:'間食'};const MEAL_ICON={breakfast:'☀',lunch:'◐',dinner:'☾',snack:'♧'};const TITLES={today:'今日の食事',recommend:'店舗別おすすめ',catalog:'メニュー図鑑',insights:'週間レポート',profile:'からだの記録',settings:'設定・データ管理'};
const SOURCES=[['マクドナルド','公式 栄養成分一覧（2026-10-20）','https://www.mcdonalds.co.jp/quality/allergy_Nutrition/nutrient/'],['マクドナルド','公式 商品・税込最低価格','https://www.mcdonalds.co.jp/menu/burger/'],['松屋','公式 牛めし・栄養成分（2026-10-13）','https://www.matsuyafoods.co.jp/matsuya/menu/gyumeshi/gyumeshi_hp_261013.html'],['すき家','公式 栄養成分表（画面の更新日2026-10-27）','https://images.zensho.co.jp/materials/sukiya/allergen/nutrition.pdf'],['すき家','公式 牛丼価格','https://www.sukiya.jp/menu/in/gyudon/100100/index.html'],['ローソン','公式 サラダチキンの栄養表示','https://www.lawson.co.jp/sp/recommend/original/detail/1507463_2168.html'],['ファミリーマート','公式 塩おむすび栄養・価格','https://www.family.co.jp/goods/omusubi/0411554.html'],['ファミリーマート','公式 おむすび栄養一覧','https://www.family.co.jp/goods/safety/goods010.html'],['セブン‐イレブン','公式 チキンロール商品情報','https://www.sej.co.jp/products/a/item/054110/'],['文部科学省','日本食品標準成分表（自炊の概算参考）','https://www.mext.go.jp/a_menu/syokuhinseibun/mext_01110.html']];
const DEFAULT_GOALS={kcal:2150,protein:105,fat:65,carbs:280,fiber:22,salt:6,budget:1000};
function dateStr(d=new Date()){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function shift(s,n){let d=new Date(s+'T12:00:00');d.setDate(d.getDate()+n);return dateStr(d)}
function readable(s){const d=new Date(s+'T12:00:00');return `${d.getMonth()+1}月${d.getDate()}日（${'日月火水木金土'[d.getDay()]}）`}
function safe(s){return String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function attr(s){return safe(s)}
function url(s){try{let u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:'#'}catch{return '#'}}
function fmt(n,d=0){return (Math.round((+n||0)*10**d)/10**d).toLocaleString('ja-JP',{maximumFractionDigits:d})}
function money(n){return n==null?'価格未確認':`¥${fmt(n)}`}
function escapeCsv(s){return '"'+String(s??'').replace(/"/g,'""')+'"'}
const loaded=window.NutriAccount ? await window.NutriAccount.ready : null;const state={page:'today',date:dateStr(),store:'all',meal:'lunch',query:'',sort:'recommended',goals:{...DEFAULT_GOALS,...(loaded?.goals||{})},logs:Array.isArray(loaded?.logs)?loaded.logs:[],custom:Array.isArray(loaded?.custom)?loaded.custom:[],extraStores:Array.isArray(loaded?.extraStores)?loaded.extraStores:[],profile:{sex:'unspecified',birth:'',age:'',height:null,weight:null,targetWeight:null,activity:'light',goal:'loss',deficit:350,waist:null,bodyFat:null,alt:null,ast:null,tg:null,hdl:null,ldl:null,glucose:null,hba1c:null,systolic:null,diastolic:null,measuredAt:'',...(loaded?.profile||{})},measurements:Array.isArray(loaded?.measurements)?loaded.measurements:[],autoGoals:loaded?.autoGoals??true,theme:loaded?.theme||'light'};
function persist(){try{window.NutriAccount.save({goals:state.goals,logs:state.logs,custom:state.custom,extraStores:state.extraStores,profile:state.profile,measurements:state.measurements,autoGoals:state.autoGoals,theme:state.theme})}catch{toast('保存に失敗しました。容量またはブラウザ設定を確認してください。')}}
function foods(){return [...(window.SEED_FOODS||[]),...state.custom]}
function food(id){return foods().find(x=>x.id===id)}
function stores(){return ['自炊・スーパー','セブン‐イレブン','ファミリーマート','ローソン','マクドナルド','松屋','すき家',...state.extraStores.filter(x=>!['自炊・スーパー','セブン‐イレブン','ファミリーマート','ローソン','マクドナルド','松屋','すき家'].includes(x))]}
function entries(date=state.date){return state.logs.filter(x=>x.date===date)}
function nutrients(logs){const keys=['kcal','protein','fat','carbs','fiber','salt','price'];const result={unknown:{}};for(const k of keys){result[k]=0;result.unknown[k]=0;for(const item of logs){if(item[k]===null || item[k]===undefined || item[k]===''){result.unknown[k]++;continue}result[k]+=Number(item[k])*(+item.qty||1)}}return result}
function current(){const es=entries();return {eaten:nutrients(es.filter(x=>x.status==='eaten')),planned:nutrients(es.filter(x=>x.status==='planned')),all:nutrients(es),items:es}}
function totalsText(total,key,dec=0){const suffix=total.unknown[key]>0?'＋未確認':' ';return `${fmt(total[key],dec)}${suffix.trim()?` ${suffix.trim()}`:''}`}
function numeric(x){return Number.isFinite(+x)?+x:0}
function foodSnapshot(f,meal,status,day=state.date){return {id:cryptoId(),foodId:f.id,store:f.store,name:f.name,date:day,meal,status,qty:1,quality:f.quality,kcal:f.kcal,protein:f.protein,fat:f.fat,carbs:f.carbs,fiber:f.fiber,salt:f.salt,price:f.price}}
function cryptoId(){return 'l'+Date.now().toString(36)+Math.random().toString(36).slice(2,8)}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('open');clearTimeout(toast._timer);toast._timer=setTimeout(()=>el.classList.remove('open'),2600)}
function progress(k,tot){let target=state.goals[k],e=tot.eaten[k]||0,p=tot.planned[k]||0;const warn=k==='salt'||k==='fat'||k==='budget'||k==='kcal';const key=k==='budget'?'price':k;if(k==='budget'){e=tot.eaten.price;p=tot.planned.price}const val=e+p;return `<div class="metric"><div class="metric-title"><span class="metric-name">${{kcal:'エネルギー',protein:'たんぱく質',fat:'脂質',carbs:'炭水化物',fiber:'食物繊維',salt:'食塩相当量',budget:'食費'}[k]}</span><span class="metric-right">${fmt(e,k==='salt'?1:0)} <span>＋予定 ${fmt(p,k==='salt'?1:0)} / ${fmt(target,k==='salt'?1:0)} ${k==='kcal'?'kcal':k==='budget'?'円':'g'}${tot.all.unknown[key]?' · 一部不明':''}</span></span></div><div class="bar ${warn&&val>target?'warning':''}"><div class="eaten" style="width:${Math.min(100,e/target*100)}%"></div><div class="planned" style="width:${Math.max(0,Math.min(100-e/target*100,p/target*100))}%"></div></div></div>`}
function badge(f){const estimated=f.quality!=='official';return `<span class="tag ${estimated?'estimated':''}">${f.quality==='official'?'公式情報':f.quality==='custom'?'自己登録':'概算'}</span>`}
function summaryStats(){const t=current();const c=t.all;const g=state.goals;return `<div class="card-grid"><div class="panel stat"><div class="icon">◉</div><div class="label">摂取済みカロリー</div><div class="num ${c.kcal>g.kcal?'warn':''}">${fmt(t.eaten.kcal)}<span class="unit">kcal</span></div><div class="sub">予定 ${fmt(t.planned.kcal)} / 目標 ${fmt(g.kcal)}</div></div><div class="panel stat"><div class="icon">♢</div><div class="label">たんぱく質</div><div class="num">${fmt(c.protein,1)}<span class="unit">g</span></div><div class="sub">摂取＋予定 / 目標 ${g.protein}g</div></div><div class="panel stat"><div class="icon">♧</div><div class="label">塩分</div><div class="num ${c.salt>g.salt?'warn':''}">${fmt(c.salt,1)}<span class="unit">g</span></div><div class="sub">摂取＋予定 / 目標上限 ${g.salt}g</div></div><div class="panel stat"><div class="icon">¥</div><div class="label">食費の残り（予定込み）</div><div class="num ${g.budget-c.price<0?'warn':'good'}">${money(g.budget-c.price)}</div><div class="sub">確定・予定 ${money(c.price)} / 上限 ${money(g.budget)}${c.unknown.price?' · 一部未確認':''}</div></div></div>`}
function dateChooser(){return `<div class="date-controls"><button class="btn btn-sm" data-action="prev" title="前の日">‹</button><input type="date" id="dayInput" value="${state.date}" aria-label="対象日"><button class="btn btn-sm" data-action="next" title="次の日">›</button><button class="btn btn-sm btn-soft" data-action="todayDate">今日</button></div>`}
function today(){const t=current();let missing=0;const mealcards=MEALS.map(m=>{const items=t.items.filter(x=>x.meal===m);const sums=nutrients(items);missing+=items.filter(x=>x.price==null).length;return `<div class="panel meal-card"><div class="meal-head"><div class="meal-ico">${MEAL_ICON[m]}</div><div><div class="meal-name">${MEAL_LABEL[m]}</div><div class="meal-meta">${fmt(sums.kcal)} kcal ・ ${money(sums.price)}${sums.unknown.price?'＋未確認':''}</div></div></div><div class="meal-body">${items.length?items.map(x=>`<div class="log-item"><div class="flex-full"><div class="log-name">${safe(x.name)} ${x.qty===1?'':`×${fmt(x.qty,1)}`}</div><div class="log-sub">${safe(x.store)} · ${fmt(x.kcal*x.qty)} kcal <span class="tiny-tag ${x.status}">${x.status==='eaten'?'食べた':'予定'}</span></div></div><div class="log-acts"><button class="icon-btn" data-action="qtyDown" data-id="${x.id}" title="数量を減らす">−</button><button class="icon-btn" data-action="toggleEat" data-id="${x.id}" title="食べた/予定を切替">${x.status==='eaten'?'↶':'✓'}</button><button class="icon-btn" data-action="qtyUp" data-id="${x.id}" title="数量を増やす">＋</button><button class="icon-btn" data-action="remove" data-id="${x.id}" title="削除">×</button></div></div>`).join(''):'<div class="empty-meal">まだ食事の記録がありません</div>'}</div><div class="meal-bottom"><button class="btn btn-sm btn-soft" data-action="recommendMeal" data-meal="${m}">✦ 提案を見る</button><button class="btn btn-sm" data-action="pickMeal" data-meal="${m}">＋ 登録</button></div></div>`}).join('');
const noted=[];if(t.all.salt>state.goals.salt)noted.push('予定を含む塩分が目標上限を超えています。調味料や汁物の量にも注意してください。');if(t.all.kcal>state.goals.kcal)noted.push('予定を含むカロリーが設定目標を超えています。運動量や空腹感に合わせて適正量を見直してください。');if(t.all.price>state.goals.budget)noted.push('現在の食費は予算を超えています。購入前に調整しましょう。');if(missing)noted.push('価格が未確認の商品があります。食費合計は一部を含みません。');
const shopping=t.items.filter(x=>x.status==='planned');const shopmap={};for(const x of shopping)(shopmap[x.store]??=[]).push(x);
return `<div class="hello"><div><div class="eyebrow">DAILY OVERVIEW</div><h1>${readable(state.date)}の食事</h1><p>「食べた」と「予定」を分けて記録し、次の食事を選べます。</p></div>${dateChooser()}</div>${healthContextRibbon()}${summaryStats()}<div class="two-col"><section class="panel pad"><div class="section-heading"><h2>栄養バランス</h2><span class="small-note">濃色＝摂取済み / 淡色＝予定</span></div><div class="metrics">${['kcal','protein','fat','carbs','fiber','salt','budget'].map(k=>progress(k,t)).join('')}</div><p class="small-note mt">一部の商品で食物繊維などが未公表のため、表示合計は把握できた値の合算です。未確認を0gと解釈しないでください。</p></section><section class="panel pad"><div class="section-heading"><h2>今日のアドバイス</h2><span class="tag">栄養・予算から算出</span></div><div class="stack">${noted.map(v=>`<div class="notice orange">${safe(v)}</div>`).join('')}${t.items.length===0?'<div class="notice"><b>まず朝食・昼食・夕食を作成</b>「1日分を自動で仮登録」からメニューを組み立てられます。</div>':''}${healthPriorities().length?healthPriorities().slice(0,2).map(x=>`<div class="notice orange"><b>${safe(x.name)}の記録を考慮</b>${safe(x.text)}</div>`).join(''):'<div class="notice">健診情報を登録すると、記録した数値に合わせて候補の優先度を調整できます。</div>'}<div class="between wrap"><button class="btn btn-primary" data-action="autoDay">✦ 1日分を自動で仮登録</button><button class="btn" data-page="recommend">店舗別提案へ →</button></div><span class="small-note">自動作成はルールベース。未入力の食事だけ追加し、自炊中心／昼は選択店舗を優先します。</span></div></section></div><div class="section-heading"><h2>食事のタイムライン</h2><span class="small-note">数量 +/− · ✓で「摂取済み」に変更</span></div><div class="meal-grid">${mealcards}</div><section class="panel pad"><div class="section-heading"><h2>購入予定リスト</h2><button class="btn btn-sm" data-action="copyShopping">リストをコピー</button></div>${shopping.length?Object.entries(shopmap).map(([s,rows])=>`<div class="between" style="margin:8px 0"><div><b>${safe(s)}</b><div class="small-note">${rows.map(x=>safe(x.name)+(x.qty!==1?' ×'+x.qty:'')).join(' / ')}</div></div><div class="bold">${money(nutrients(rows).price)}${nutrients(rows).unknown.price?'＋未確認':''}</div></div>`).join(''):'<div class="small-note">「予定」として登録した商品がここに並びます。</div>'}</section>`}
function storeSelector(){return `<div class="store-row">${['all',...stores()].map(s=>`<button class="chip ${state.store===s?'active':''}" data-store="${attr(s)}">${s==='all'?'すべての店舗':safe(s)}</button>`).join('')}</div>`}
function foodKind(f){if(f.store==='自炊・スーパー')return f.kind||'food';if(['松屋','すき家'].includes(f.store))return 'meal';if(f.store==='マクドナルド')return 'main';if(f.store==='ローソン')return 'protein';if(f.name.includes('ロール'))return 'main';if(f.name.includes('ランチ'))return 'meal';if(f.name.includes('おむすび')||f.name.includes('むすび'))return 'rice';return f.kind||'food'}
function validCombo(items){const kinds=items.map(foodKind);if(kinds.filter(k=>k==='meal').length>0&&items.length>1)return false;if(kinds.filter(k=>k==='main').length>1)return false;if(kinds.filter(k=>k==='rice').length>1)return false;if(kinds.filter(k=>k==='protein').length>1)return false;if(kinds.filter(k=>k==='drink').length>1)return false;if(kinds.filter(k=>k==='fruit').length>1)return false;if(kinds.filter(k=>k==='snack').length>1)return false;if(kinds.filter(k=>k==='vegetable').length>2)return false;return true}
function combine(items){let r={kcal:0,protein:0,fat:0,carbs:0,salt:0,fiber:0,price:0,unknownFiber:0};for(const x of items){for(const k of ['kcal','protein','fat','carbs','salt','price','fiber']){if(x[k]===null||x[k]===undefined){if(k==='fiber')r.unknownFiber++;continue}r[k]+=x[k]}}return r}
function candidates(day,meal,store){const foods0=foods().filter(f=>(store==='all'||f.store===store) && (f.time==='any'||f.time===meal) && f.price!=null);const cur=nutrients(state.logs.filter(x=>x.date===day));const mealUsed=nutrients(state.logs.filter(x=>x.date===day&&x.meal===meal));const budgetRemaining=Math.max(0,state.goals.budget-cur.price);const kcRemaining=Math.max(0,state.goals.kcal-cur.kcal);const factors={breakfast:.27,lunch:.36,dinner:.33,snack:.10};const aim=Math.max(80,Math.min(state.goals.kcal*factors[meal]-mealUsed.kcal,kcRemaining));const proteinAim=Math.max(9,Math.min(42,(state.goals.protein-cur.protein)*.43));const fiberAim=Math.max(1,Math.min(9,(state.goals.fiber-cur.fiber)*.40));let result=[];function evaluate(items){if(!validCombo(items))return;const v=combine(items);if(v.price>budgetRemaining+0.01 || v.kcal>kcRemaining*1.2+90 ||v.salt>Math.max(1.5,(state.goals.salt-cur.salt)*1.2)&& v.salt>2.2)return;let score=100;score-=Math.abs(v.kcal-aim)/Math.max(aim,250)*43;score-=Math.max(0,proteinAim-v.protein)*1.25;score-=Math.max(0,v.fat-22)*1.2;score-=Math.max(0,v.salt-1.7)*8;score-=Math.max(0,v.salt-(state.goals.salt-cur.salt))*19;if(state.profile.systolic>=130||state.profile.diastolic>=85)score-=Math.max(0,v.salt-1.35)*5;if(state.profile.tg>=150){score+=Math.min(5,v.fiber*.65);score-=Math.max(0,v.carbs-aim*.60/4)*.2;}score-=v.price/Math.max(150,state.goals.budget)*9;score+=Math.min(10,v.fiber/Math.max(1,fiberAim)*8);score-=v.unknownFiber*2.2;if(items.some(f=>f.quality==='estimate'))score-=4;if(items.some(f=>f.price_type==='from'))score-=1;const cnt=entries(day).filter(x=>items.some(f=>f.id===x.foodId)).length;score-=cnt*8;if(items.length>=2&&v.kcal>=aim*.65&&v.protein>=proteinAim*.65)score+=5;if(items.length===3&&v.kcal<aim*.35)score-=14;result.push({items,v,score,reason:reasonFor(v,aim,proteinAim,budgetRemaining)})}
let maxCandidates=store==='all'?foods0.slice(0,42):foods0.slice(0,28);for(let i=0;i<maxCandidates.length;i++){evaluate([maxCandidates[i]]);for(let j=i+1;j<maxCandidates.length;j++){if(maxCandidates[i].store!==maxCandidates[j].store && store==='all')continue;evaluate([maxCandidates[i],maxCandidates[j]]);for(let k=j+1;k<maxCandidates.length;k++){if(maxCandidates[i].store!==maxCandidates[k].store && store==='all')continue;evaluate([maxCandidates[i],maxCandidates[j],maxCandidates[k]])}}}
result.sort((a,b)=>b.score-a.score);return result.slice(0,20)}
function reasonFor(v,aim,proteinAim,budget){let r=[];if(v.protein>=proteinAim)r.push('たんぱく質を確保');if(v.fiber>=5)r.push('食物繊維が比較的豊富');if(v.salt<=1.5)r.push(state.profile.systolic>=130?'血圧の記録を踏まえ塩分控えめ':'塩分が比較的少なめ');if(state.profile.tg>=150&&v.fiber>=4)r.push('中性脂肪の記録を踏まえ繊維を優先');if(v.kcal<aim*.6)r.push('食事としてはエネルギーが少なめ');if(v.price<=budget*.5)r.push('予算に余裕');return (r.length?r:['現在の残り目標と予算から選定']).slice(0,3).join(' · ')}
function recommendation(){let cur=current(),result=candidates(state.date,state.meal,state.store);let hasUnknown=cur.all.unknown.price>0;
return `<div class="hello"><div><div class="eyebrow">SMART STORE RECOMMENDER</div><h1>今、何を買うべき？</h1><p>今日食べたものと予定、残りの栄養・予算から購入候補を計算します。</p></div>${dateChooser()}</div><div class="panel pad mb"><div class="section-heading"><h2>購入する店舗を選択</h2><span class="small-note">選択した店舗の商品だけを組み合わせます</span></div>${storeSelector()}<div class="divider"></div><div class="filters"><div class="field"><label>おすすめする食事</label><select id="mealSelect">${MEALS.map(m=>`<option value="${m}" ${state.meal===m?'selected':''}>${MEAL_LABEL[m]}</option>`).join('')}</select></div><div class="field"><label>残りの予算（予定を含む）</label><input value="${money(Math.max(0,state.goals.budget-cur.all.price))}${hasUnknown?'＋未確認商品あり':''}" disabled></div><button class="btn btn-dark" data-page="catalog">商品データを見る →</button></div></div>${healthContextRibbon()}<div class="section-heading"><h2>おすすめの購入候補</h2><span class="small-note">${result.length}パターン計算 · 点数は独自の適合度です</span></div>${result.length?`<div class="reco-top">${result.slice(0,6).map((r,i)=>`<div class="panel reco-card"><span class="reco-kicker">${i===0?'BEST MATCH / 最優先':`OPTION ${i+1}`} · ${safe(r.items[0].store)}</span><h3>${r.items.length===1?safe(r.items[0].name):`${r.items.length}商品の組み合わせ`}</h3><div class="reco-items">${r.items.map(f=>safe(f.name)).join(' ＋ ')}</div><div class="reco-stats"><span>${fmt(r.v.kcal)} kcal</span><span>P ${fmt(r.v.protein,1)}g</span><span>脂質 ${fmt(r.v.fat,1)}g</span><span>塩分 ${fmt(r.v.salt,1)}g</span><span>食物繊維 ${fmt(r.v.fiber,1)}g${r.v.unknownFiber?'＋不明':''}</span></div><div class="reco-reason">✦ ${safe(r.reason)}${r.items.some(f=>f.quality==='estimate')?' · 概算データを含みます':''}</div><div class="reco-footer"><strong>${money(r.v.price)}<small> / 目安</small></strong><button class="btn btn-primary btn-sm" data-action="chooseReco" data-idx="${i}">予定に追加 ＋</button></div></div>`).join('')}</div><p class="small-note">価格未確認商品は自動推薦から除外しています。「〜円」価格は最低表示価格のため、店舗で高くなる場合があります。1食だけで必要栄養素を満たすとは限りません。</p>`:'<div class="panel empty-state"><div class="emoji">◌</div><b>この条件に合う商品がありません</b><p>店舗・時間帯を変更するか、目標予算を見直してください。価格未登録の商品は推薦対象外です。</p></div>'}<div class="panel pad mt"><div class="section-heading"><h2>計算に使用した今日の残り目標</h2><small>摂取＋予定を差し引いた量</small></div><div class="pill-stats">${[['kcal','kcal'],['protein','g'],['fiber','g'],['salt','g'],['budget','円']].map(([k,u])=>`<span>${{kcal:'エネルギー',protein:'たんぱく質',fiber:'食物繊維',salt:'塩分の残枠',budget:'予算の残り'}[k]}：${fmt(Math.max(0,state.goals[k]-cur.all[k==='budget'?'price':k]),k==='salt'?1:0)}${u}</span>`).join('')}</div></div>`}
function searchFilter(arr){let q=state.query.trim().toLowerCase();return arr.filter(f=>(state.store==='all'||f.store===state.store)&&(!q||`${f.name} ${f.store}`.toLowerCase().includes(q)))}
function catalog(){let all=searchFilter(foods());if(state.sort==='kcal')all.sort((a,b)=>a.kcal-b.kcal);if(state.sort==='protein')all.sort((a,b)=>b.protein-a.protein);if(state.sort==='price')all.sort((a,b)=>(a.price??1e8)-(b.price??1e8));if(state.sort==='salt')all.sort((a,b)=>a.salt-b.salt);
return `<div class="hello"><div><div class="eyebrow">NUTRITION DATABASE</div><h1>メニュー図鑑</h1><p>公式情報と自炊の概算値を明確に分けて表示。商品を追加・修正できます。</p></div><button class="btn btn-dark" data-action="addFood">＋ 商品を登録</button></div><div class="panel pad mb"><div class="section-heading"><h2>購入場所</h2><small>${foods().length}種類のメニュー</small></div>${storeSelector()}<div class="divider"></div><div class="catalog-toolbar"><input class="field" id="queryInput" placeholder="商品名・店舗名で検索" value="${attr(state.query)}"><select class="field" id="sortInput"><option value="recommended">標準順</option><option value="kcal" ${state.sort==='kcal'?'selected':''}>低カロリー順</option><option value="protein" ${state.sort==='protein'?'selected':''}>高たんぱく質順</option><option value="salt" ${state.sort==='salt'?'selected':''}>低塩分順</option><option value="price" ${state.sort==='price'?'selected':''}>低価格順</option></select><button class="btn" data-action="addStore">＋ 店舗を追加</button></div><p class="small-note">公式情報でも価格・規格が変わる場合があります。食物繊維が未公開の場合は「—」と表示し、0gとして扱いません。</p></div><div class="food-list">${all.map(f=>`<div class="food-row"><div class="food-main"><div class="food-name">${safe(f.name)}</div><div class="food-sub"><span>${safe(f.store)}</span>${badge(f)}<span>${fmt(f.kcal)} kcal</span><span>たんぱく質 ${fmt(f.protein,1)}g</span><span>脂質 ${fmt(f.fat,1)}g</span><span>塩分 ${fmt(f.salt,1)}g</span><span>食物繊維 ${f.fiber==null?'—':fmt(f.fiber,1)+'g'}</span></div><div class="small-note">${safe(f.note||'')} ${f.source?`<a href="${url(f.source)}" target="_blank" rel="noopener noreferrer">出典を確認 ↗</a>`:''}</div></div><div class="food-actions"><div class="food-price">${money(f.price)}${f.price_type==='from'?'<small>〜</small>':''}</div><button class="btn btn-sm btn-soft" data-action="addEntry" data-id="${f.id}">＋ 記録</button>${f.quality==='custom'?`<button class="btn btn-sm" data-action="editFood" data-id="${f.id}">編集</button>`:''}</div></div>`).join('')||'<div class="empty-state panel">該当する商品がありません。検索条件を変えるか、商品を登録してください。</div>'}</div>`}
function insights(){const dates=Array.from({length:7},(_,i)=>shift(state.date,i-6));const dayTotals=dates.map(s=>({date:s,t:nutrients(entries(s).filter(x=>x.status==='eaten'))}));const used=dayTotals.filter(x=>entries(x.date).some(l=>l.status==='eaten'));
const average=(k)=>used.length?used.reduce((a,x)=>a+x.t[k],0)/used.length:0;
return `<div class="hello"><div><div class="eyebrow">WEEKLY REPORT</div><h1>直近7日間の記録</h1><p>食べたと記録した内容のみで集計します。未入力の日は平均から除外します。</p></div>${dateChooser()}</div><div class="card-grid"><div class="panel stat"><div class="label">記録した日</div><div class="num">${used.length}<span class="unit">/ 7日</span></div></div><div class="panel stat"><div class="label">平均摂取カロリー</div><div class="num">${fmt(average('kcal'))}<span class="unit">kcal</span></div></div><div class="panel stat"><div class="label">平均たんぱく質</div><div class="num">${fmt(average('protein'),1)}<span class="unit">g</span></div></div><div class="panel stat"><div class="label">平均食費</div><div class="num">${fmt(average('price'))}<span class="unit">円</span></div></div><div class="insight-grid"><div class="panel pad"><div class="section-heading"><h2>エネルギーの推移</h2><span class="small-note">摂取済み kcal</span></div><div class="week-bars">${dayTotals.map(x=>`<div class="week-col"><div class="wvalue">${x.t.kcal?fmt(x.t.kcal):'—'}</div><div class="wbar"><div class="filled" style="height:${Math.min(100,x.t.kcal/Math.max(150,state.goals.kcal)*100)}%"></div></div><div class="wday">${'日月火水木金土'[new Date(x.date+'T12:00').getDay()]} ${+x.date.slice(8)}</div></div>`).join('')}</div><p class="small-note mt">棒が低い日でも、食事未入力の可能性があります。グラフは健康状態の判定ではありません。</p></div><div class="panel pad"><div class="section-heading"><h2>1日平均の栄養</h2></div><div class="metrics">${[['protein','たんぱく質'],['fat','脂質'],['carbs','炭水化物'],['fiber','食物繊維'],['salt','塩分']].map(([k,n])=>`<div class="metric"><div class="metric-title"><span class="metric-name">${n}</span><span class="metric-right">${fmt(average(k),1)} <span>/ ${state.goals[k]} g</span></span></div><div class="bar"><div class="eaten" style="width:${Math.min(100,average(k)/state.goals[k]*100)}%"></div></div></div>`).join('')}</div><p class="small-note mt">栄養値の未公表項目は計算に含まれません。</p></div></div><div class="panel pad mt"><div class="section-heading"><h2>データの書き出し</h2></div><button class="btn btn-dark" data-action="exportCSV">食事記録をCSVで保存</button> <button class="btn" data-action="exportJSON">バックアップJSONを保存</button></div>`}
function settings(){const g=state.goals;return `<div class="hello"><div><div class="eyebrow">PERSONALIZE & DATA SAFETY</div><h1>目標をカスタマイズ</h1><p>初期値は暫定的な例です。年齢・活動量・治療方針に合わせて調整してください。</p></div></div><div class="settings-grid"><section class="panel pad"><div class="section-heading"><h2>1日の目標</h2></div><form id="goalsForm"><div class="form-row">${[['kcal','カロリー（kcal）'],['budget','食費（円）'],['protein','たんぱく質（g）'],['fat','脂質（g）'],['carbs','炭水化物（g）'],['fiber','食物繊維（g）'],['salt','食塩相当量（g・上限）']].map(([k,n])=>`<div class="field"><label for="g_${k}">${n}</label><input type="number" id="g_${k}" name="${k}" required min="${k==='salt'?'1':k==='fiber'?'1':'10'}" max="${k==='budget'?100000:10000}" step="${k==='salt'?'0.1':'1'}" value="${g[k]}"></div>`).join('')}</div><p class="small-note mt">初期設定：2,150kcal / たんぱく質105g / 脂質65g / 炭水化物280g / 食物繊維22g / 食塩6g未満 / 1,000円。個別の必要量を診断したものではありません。</p><button class="btn btn-primary mt" type="submit">設定を保存</button> <button class="btn mt" type="button" data-action="resetGoals">初期値に戻す</button></form></section><section class="panel pad"><div class="section-heading"><h2>データの管理</h2></div><div class="stack"><div class="notice"><b>${window.NutriAccount.isSignedIn()?'アカウントに同期':'この端末だけに保存'}</b>${window.NutriAccount.isSignedIn()?'食事・身体データをクラウドに保存します。同期状態は画面上部で確認できます。ログアウトするとこの端末のアカウント用キャッシュを削除します。':'ログインすると複数端末で共有できます。未ログインの記録は自動送信されません。ブラウザのデータ削除で端末内の記録は消えます。'}</div><div><button class="btn btn-dark" data-action="exportJSON">すべてをJSONでバックアップ</button></div><div><button class="btn" data-action="exportCSV">履歴CSVを書き出す</button></div><div class="field"><label>以前のバックアップJSONを読み込み（既存データを置換）</label><input id="importFile" type="file" accept=".json,application/json"></div><div class="divider"></div><button class="btn btn-danger" data-action="clearLogs">食事記録のみ削除</button></div></section></div><div class="settings-grid mt"><section class="panel pad"><div class="section-heading"><h2>栄養・価格データの扱い</h2></div><p class="small-note">「公式情報」はメーカー・チェーン公式サイトの掲載値をもとにした初期例です。「概算」は一般食材・自炊を想定した例で、実測値ではありません。価格は店舗・地域・時期・持ち帰りなどで変わります。最新の商品包装と公式掲載を必ず確認してください。</p><p class="small-note">アレルギー、糖尿病・腎疾患、肝疾患治療などの医学的な制限は自動的に安全判定できません。既存の健診結果に関する診療は医師に相談してください。</p><p class="small-note">食物繊維は公表されていないチェーン商品があり、「— / 不明」で管理。完全な栄養充足判定ではありません。独自の推奨順位はカロリー・PFC・塩分・繊維・予算を考慮した単純なルールでAIモデルは使用していません。</p></section><section class="panel pad"><div class="section-heading"><h2>公式参考リンク</h2></div><div class="info-list">${SOURCES.map(r=>`<div class="source-item"><b>${safe(r[0])} — ${safe(r[1])}</b><a href="${url(r[2])}" target="_blank" rel="noopener noreferrer">${safe(r[2])}</a></div>`).join('')}</div></section></div>`}
/* -- Health profile + screenshot intake (v2) --------------------------------- */
const PROFILE_DEFAULT={sex:'unspecified',birth:'',age:'',height:null,weight:null,targetWeight:null,activity:'light',goal:'loss',deficit:350,waist:null,bodyFat:null,alt:null,ast:null,tg:null,hdl:null,ldl:null,glucose:null,hba1c:null,systolic:null,diastolic:null,measuredAt:''};
const PROFILE_FIELDS=[
  ['height','身長','cm',90,250,0.1],['weight','体重','kg',20,350,0.1],['waist','腹囲','cm',35,220,0.1],['bodyFat','体脂肪率','%',2,70,0.1],
  ['alt','ALT（GPT）','U/L',0,3000,1],['ast','AST（GOT）','U/L',0,3000,1],['tg','中性脂肪','mg/dL',0,2000,1],
  ['hdl','HDLコレステロール','mg/dL',0,300,1],['ldl','LDLコレステロール','mg/dL',0,500,1],
  ['glucose','空腹時血糖','mg/dL',20,700,1],['hba1c','HbA1c','%',2,20,0.1],
  ['systolic','収縮期血圧（上）','mmHg',50,260,1],['diastolic','拡張期血圧（下）','mmHg',35,160,1]
];
let photoFile=null,photoObjectURL=null,ocrBusy=false;
function valueInput(key,label,unit,min,max,step,current=state.profile){return `<div class="field"><label for="p_${key}">${label} <span class="unit-label">${unit}</span></label><input id="p_${key}" name="${key}" type="number" inputmode="decimal" min="${min}" max="${max}" step="${step}" value="${current?.[key]??''}" placeholder="未登録"></div>`}
function calcAge(p){if(p.birth){const b=new Date(p.birth+'T12:00:00'),n=new Date();if(!Number.isFinite(b.getTime())||b>n)return null;let age=n.getFullYear()-b.getFullYear()-(n.getMonth()<b.getMonth()||n.getMonth()===b.getMonth()&&n.getDate()<b.getDate()?1:0);return age>=0&&age<=115?age:null}if(p.age!==''&&p.age!=null){const a=Number(p.age);return Number.isFinite(a)&&a>=0&&a<=115?a:null}return null}
function calculatePersonalGoals(p){const age=calcAge(p),h=Number(p.height),w=Number(p.weight);if(age==null||age<18||!Number.isFinite(h)||h<100||!Number.isFinite(w)||w<30||!['male','female'].includes(p.sex))return null;const mult={sedentary:1.2,light:1.375,moderate:1.55,high:1.725}[p.activity]||1.375;
 const bmr=10*w+6.25*h-5*age+(p.sex==='male'?5:-161);const maintenance=bmr*mult;const reduction=p.goal==='loss'?Math.max(150,Math.min(600,Number(p.deficit)||350)):p.goal==='gain'?-250:0;
 const kcal=Math.round(Math.max(p.sex==='male'?1500:1200,Math.min(4400,maintenance-reduction))/25)*25;
 const protein=Math.round(w*(p.goal==='loss'?1.25:1.05));const fat=Math.round(kcal*.27/9);const carbs=Math.max(50,Math.round((kcal-protein*4-fat*9)/4));
 return {kcal,protein,fat,carbs,fiber:Math.max(22,Math.round(kcal/1000*10)),salt:6,budget:state.goals.budget,bmr:Math.round(bmr),maintenance:Math.round(maintenance),age};}
function bmi(){const p=state.profile;return p.height>0&&p.weight>0?p.weight/((p.height/100)**2):null}
function healthPriorities(){const p=state.profile,items=[];if(p.alt!=null&&p.alt>30)items.push({name:'肝機能',text:'ALTが基準を超える記録があります。食事管理だけで判断せず、医療機関での原因確認を優先してください。',kind:'warning'});
 if((p.systolic!=null&&p.systolic>=130)||(p.diastolic!=null&&p.diastolic>=85))items.push({name:'血圧',text:'血圧が高めの記録に合わせ、塩分が少ない商品を優先します。',kind:'soft'});
 if(p.tg!=null&&p.tg>=150)items.push({name:'中性脂肪',text:'中性脂肪の記録を踏まえ、食物繊維が多めの食品を評価します。糖類は商品データがないため判定できません。',kind:'soft'});
 if(bmi()!=null&&bmi()>=25)items.push({name:'体重',text:'BMIが25以上のため、活動量と目標に応じた摂取エネルギーの調整を推奨します。',kind:'soft'});
 return items}
function healthContextRibbon(){const p=state.profile,calc=calculatePersonalGoals(p);if(!p.weight&&!p.height)return `<div class="profile-prompt"><div class="prompt-glyph">◎</div><div><b>身体データを登録して献立をパーソナライズ</b><p>体重・身長・健診のスクショを読み取り、毎日の栄養目標に反映できます。</p></div><button class="btn btn-primary btn-sm" data-page="profile">登録する</button></div>`;
 const data=[p.weight?`体重 ${fmt(p.weight,1)}kg`:null,bmi()?`BMI ${fmt(bmi(),1)}`:null,calc?`推定目標 ${fmt(state.goals.kcal)}kcal`:null].filter(Boolean);
 return `<div class="profile-mini"><div><div class="small-note">登録された身体データを参照中</div><b>${data.map(safe).join(' ・ ')}</b><div class="small-note">${healthPriorities().map(x=>x.name).join('・')||'登録済みの身体データ'}を考慮して食事候補を算出</div></div><button class="btn btn-sm" data-page="profile">プロフィールを編集 →</button></div>`;
}
function weightChart(){const h=(state.measurements||[]).filter(x=>Number.isFinite(+x.weight)&&+x.weight>0).slice().sort((a,b)=>a.date.localeCompare(b.date)).slice(-15);if(h.length<2)return '<div class="small-note">体重を2回以上記録すると推移グラフが表示されます。</div>';
 const values=h.map(x=>+x.weight),mi=Math.min(...values)-1,ma=Math.max(...values)+1,span=ma-mi||1;
 const pts=values.map((v,i)=>`${18+i*(304/(values.length-1))},${100-(v-mi)/span*76}`).join(' ');
 return `<svg class="weight-chart" viewBox="0 0 340 125" role="img" aria-label="体重推移グラフ"><line x1="12" y1="103" x2="330" y2="103" stroke="var(--line)"/><line x1="12" y1="26" x2="330" y2="26" stroke="var(--line)" stroke-dasharray="3 5"/><polyline points="${pts}" fill="none" stroke="var(--green)" stroke-width="3.5" stroke-linejoin="round" stroke-linecap="round"/>${pts.split(' ').map(s=>{let [x,y]=s.split(',');return `<circle cx="${x}" cy="${y}" r="3.5" fill="var(--green)"/>`}).join('')}<text x="12" y="119" font-size="10" fill="var(--muted)">${safe(h[0].date)}</text><text x="250" y="119" font-size="10" fill="var(--muted)">${safe(h[h.length-1].date)}</text></svg>`;
}
function profilePage(){const p=state.profile,calc=calculatePersonalGoals(p);const b=bmi(),prio=healthPriorities();const profileVal=x=>x==null?'—':fmt(x,1);
 const physical=PROFILE_FIELDS.slice(0,4),medical=PROFILE_FIELDS.slice(4);
 const priorities=prio.length?prio.map(x=>`<div class="notice ${x.kind==='warning'?'orange':''}"><b>${safe(x.name)}の記録を反映</b>${safe(x.text)}</div>`).join(''):'<div class="notice">身体データを入力すると、栄養・塩分・食費に合わせて提案します。</div>';
 return `<div class="hello"><div><div class="eyebrow">PERSONAL HEALTH PROFILE</div><h1>からだの記録</h1><p>身体情報や健診スクショを登録し、食事提案の条件を調整できます。</p></div><button class="btn btn-primary" data-action="openHealthImport">▧ スクショを取り込む</button></div>
 <div class="profile-summary-grid"><div class="profile-primary panel"><div class="small-note">現在の体重</div><div class="profile-big">${profileVal(p.weight)}<span>kg</span></div><div class="small-note">BMI ${b==null?'未計算':fmt(b,1)} ${p.targetWeight?` · 目標 ${fmt(p.targetWeight,1)}kg`:''}</div></div><div class="panel profile-primary"><div class="small-note">推定1日エネルギー目標</div><div class="profile-big">${calc?fmt(calc.kcal):'—'}<span>kcal</span></div><div class="small-note">${calc?`基礎代謝 ${fmt(calc.bmr)} / 維持 ${fmt(calc.maintenance)}kcal`:'年齢・体重・身長・計算用区分を登録'}</div></div></div>
 <div class="profile-layout"><section class="panel pad"><div class="section-heading"><h2>基本情報と目標</h2><span class="tag">保存後、献立に反映</span></div>
 <form id="profileForm"><div class="form-row"><div class="field"><label>生年月日</label><input type="date" name="birth" max="${dateStr()}" value="${attr(p.birth||'')}"></div><div class="field"><label>年齢（生年月日を入力しない場合）</label><input type="number" name="age" min="0" max="115" inputmode="numeric" value="${attr(p.age??'')}" placeholder="例：22"></div>
 <div class="field"><label>基礎代謝の推定計算用区分</label><select name="sex"><option value="unspecified" ${p.sex==='unspecified'?'selected':''}>選択しない</option><option value="male" ${p.sex==='male'?'selected':''}>男性式</option><option value="female" ${p.sex==='female'?'selected':''}>女性式</option></select></div>
 <div class="field"><label>日常の活動量</label><select name="activity">${[['sedentary','座りがち（運動少なめ）'],['light','軽い活動（週1〜3回程度）'],['moderate','普通（週3〜5回程度）'],['high','活動的（ほぼ毎日）']].map(x=>`<option value="${x[0]}" ${p.activity===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div>
 <div class="field"><label>目標</label><select name="goal">${[['loss','無理なく減量'],['maintain','現状を維持'],['gain','少しずつ増量']].map(x=>`<option value="${x[0]}" ${p.goal===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div>
 <div class="field"><label>減量時の摂取調整（kcal/日）</label><select name="deficit">${[250,350,450].map(x=>`<option value="${x}" ${+p.deficit===x?'selected':''}>-${x} kcal / 日</option>`).join('')}</select></div>
 </div><div class="form-row mt">${physical.map(([key,label,unit,min,max,step])=>valueInput(key,label,unit,min,max,step)).join('')}<div class="field"><label>目標体重 kg</label><input type="number" name="targetWeight" min="20" max="350" step="0.1" inputmode="decimal" value="${p.targetWeight??''}" placeholder="任意"></div><div class="field"><label>測定日</label><input type="date" name="measuredAt" value="${attr(p.measuredAt||dateStr())}"></div></div>
 <div class="section-heading mt"><h2>健康診断・測定値（任意）</h2></div><div class="form-row">${medical.map(([key,label,unit,min,max,step])=>valueInput(key,label,unit,min,max,step)).join('')}</div>
 <label class="checkbox-row mt"><input name="autoGoals" type="checkbox" ${state.autoGoals?'checked':''}> <span><b>プロフィールに合わせて目標を自動更新</b><small>体格・年齢・活動量から概算カロリーとPFCを設定。費用上限は変更しません。</small></span></label>
 <div class="form-actions mt"><button class="btn btn-primary" type="submit">プロフィールを保存して献立に反映</button><button class="btn" type="button" data-action="openHealthImport">画像から登録</button></div><p class="small-note mt">推定計算は18歳以上向けの簡易式（Mifflin–St Jeor式）です。妊娠・授乳、疾患の治療、激しいスポーツなどには対応しません。医師・管理栄養士の方針が優先です。</p></form></section>
 <div class="stack"><section class="panel pad"><div class="section-heading"><h2>プロフィールに基づく食事方針</h2></div>${priorities}<div class="notice"><b>栄養目標の使い方</b>身長・体重・年齢・活動量を登録すると、推定必要量に応じた1日の摂取量を計算します。健診の数値は塩分・食物繊維などの優先度に反映します。</div><button class="btn btn-sm btn-soft mt" data-page="recommend">条件に合う購入候補を見る →</button></section>
 <section class="panel pad"><div class="section-heading"><h2>体重の推移</h2></div>${weightChart()}<div class="history-list">${(state.measurements||[]).slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6).map(x=>`<div class="history-row"><div><b>${safe(x.date)}</b><div class="small-note">${safe(x.source==='screen_capture'?'画像から確認':'手入力')}</div></div><div><b>${x.weight==null?'—':fmt(x.weight,1)+'kg'}</b>${x.waist==null?'':`<div class="small-note">腹囲 ${fmt(x.waist,1)}cm</div>`}</div><button class="icon-btn" data-action="deleteMeasurement" data-id="${attr(x.id)}" title="履歴を削除">×</button></div>`).join('')||'<div class="small-note">まだ履歴がありません。</div>'}</div></section>
 <section class="panel pad"><h2>プライバシー</h2><p class="small-note">選択した画像はブラウザ内で一時的に表示し、画像自体・OCR全文・名前・住所は保存しません。確認した数値だけを端末内に保存します。OCRライブラリの初回読込にはネット接続が必要です。</p><button class="btn btn-sm btn-danger mt" data-action="clearProfile">身体データと測定履歴を削除</button></section></div></div>`;
}
function closePhoto(){if(photoObjectURL){URL.revokeObjectURL(photoObjectURL);photoObjectURL=null}photoFile=null;ocrBusy=false}
function openHealthImport(){closePhoto();const review=PROFILE_FIELDS.map(([key,label,unit,min,max,step])=>`<div class="field"><label for="ocr_${key}">${label} <span class="unit-label">${unit}</span></label><input name="${key}" id="ocr_${key}" type="number" step="${step}" min="${min}" max="${max}" inputmode="decimal" placeholder="未検出／空欄"></div>`).join('');
 document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal health-modal" role="dialog" aria-modal="true" aria-label="健康情報を画像から取り込み"><div class="modal-header"><h2>スクリーンショットから登録</h2><button class="icon-btn" data-action="closeModal" aria-label="閉じる">✕</button></div><div class="notice"><b>画像を選択 → 読み取り → 数値を確認して保存</b>健康診断表、体重計アプリ、体組成計の画像（PNG/JPEG/WebP）に対応。画像・OCR全文を保存しません。</div><div class="field mt"><label>画像・写真</label><input type="file" id="healthImageFile" accept="image/png,image/jpeg,image/webp,image/*"></div><img id="healthPreview" class="health-preview hide" alt="選択したスクリーンショット"><div id="healthOcrStatus" class="small-note mt" role="status">画像を選択すると自動読み取りを試みます。初回はネット接続が必要です。</div><div class="form-actions mt"><button class="btn btn-primary btn-sm" data-action="readHealthImage" id="ocrReadButton">▧ 画像を読み取る</button><button class="btn btn-sm" data-action="parseHealthText">テキストから抽出</button></div><div class="field mt"><label>読み取ったテキスト（修正・貼り付け可）</label><textarea id="healthRawText" rows="4" placeholder="例：身長 183.4cm\n体重 92.6kg\nALT 78\n中性脂肪 163\n血圧 131/76"></textarea></div><div class="divider"></div><form id="healthReviewForm"><div class="between wrap"><h3>保存する候補値を確認</h3><span class="tag" id="healthMatchedCount">未抽出</span></div><p class="small-note mb">誤読がある場合は必ず直してください。空欄は既存の登録値を変更しません。実際の基準値・正常値を結果と誤認している場合があります。</p><div class="form-row">${review}</div><div class="form-row mt"><div class="field"><label>生年月日（読み取り任意）</label><input id="ocr_birth" type="date" name="birth"></div><div class="field"><label>年齢（任意）</label><input id="ocr_age" type="number" name="age" min="0" max="115" placeholder="未検出"></div><div class="field"><label>推定計算用区分（任意）</label><select id="ocr_sex" name="sex"><option value="unspecified">変更しない</option><option value="male">男性式</option><option value="female">女性式</option></select></div><div class="field"><label>測定・受診日</label><input type="date" id="healthMeasuredAt" name="measuredAt" value="${dateStr()}"></div></div><div class="modal-footer"><button class="btn" type="button" data-action="closeModal">キャンセル</button><button class="btn btn-primary" type="submit">確認した数値を登録</button></div></form></div></div>`;
}
function healthStatus(msg,isError=false){const s=document.getElementById('healthOcrStatus');if(s){s.textContent=msg;s.classList.toggle('ocr-error',isError)}}
function applyOcrText(){const t=document.getElementById('healthRawText')?.value||'';const parsed=window.NutriHealthOCR?.parse(t);if(!parsed){healthStatus('抽出モジュールが読み込めませんでした',true);return}for(const [k,v] of Object.entries(parsed.values)){if(k==='measuredAt'){const el=document.getElementById('healthMeasuredAt');if(el)el.value=v;continue}if(['birth','age','sex'].includes(k)){const el=document.getElementById('ocr_'+k);if(el)el.value=v;continue}const input=document.getElementById('ocr_'+k);if(input)input.value=v}
 const count=document.getElementById('healthMatchedCount');if(count)count.textContent=parsed.matched+'項目を抽出';healthStatus(parsed.matched?`${parsed.matched}項目の候補を抽出しました。元画像と照合して保存してください。`:'数値を抽出できませんでした。画像と照らして手入力できます。');}
function loadScript(src){return new Promise((resolve,reject)=>{if(window.Tesseract){resolve();return}const el=document.createElement('script');el.src=src;el.async=true;el.onload=resolve;el.onerror=()=>reject(new Error('OCRライブラリを読み込めませんでした'));document.head.appendChild(el)})}
async function readHealthImage(){if(ocrBusy)return;if(!photoFile){healthStatus('画像を先に選択してください',true);return}ocrBusy=true;const btn=document.getElementById('ocrReadButton');if(btn)btn.disabled=true;let worker;
 try{healthStatus('OCRエンジンの準備中…初回は日本語データのダウンロードに時間がかかります。');if(!window.Tesseract)await loadScript('https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/tesseract.min.js');
 if(!window.Tesseract?.createWorker)throw new Error('OCRが利用できません');
 worker=await window.Tesseract.createWorker('jpn+eng',1,{logger:m=>{if(m?.status){const percent=m.progress!=null?' '+Math.round(m.progress*100)+'%':'';healthStatus('画像解析中：'+m.status+percent)}}});
 const result=await worker.recognize(photoFile);const area=document.getElementById('healthRawText');if(area){area.value=(result.data?.text||'').slice(0,24000);applyOcrText();}
 }catch(err){healthStatus('自動OCRは利用できませんでした（通信・ブラウザ設定など）。画像を見ながら数値を直接入力するか、画像内テキストを貼り付けてください。',true);}
 finally{if(worker)try{await worker.terminate()}catch{}ocrBusy=false;if(btn)btn.disabled=false}}
function validProfileNumeric(raw,meta){if(raw==null||String(raw).trim()==='')return null;const n=Number(raw);if(!Number.isFinite(n)||n<meta[3]||n>meta[4])throw new Error(meta[1]+'の入力値を確認してください');return n}
function captureMeasurement(source){const p=state.profile;if(p.weight==null&&p.waist==null)return;const prev=state.measurements[state.measurements.length-1];const item={id:cryptoId(),date:p.measuredAt||dateStr(),weight:p.weight,waist:p.waist,bodyFat:p.bodyFat,source};if(prev&&prev.date===item.date&&prev.weight===item.weight&&prev.waist===item.waist&&prev.bodyFat===item.bodyFat)return;state.measurements.push(item);if(state.measurements.length>400)state.measurements=state.measurements.slice(-400)}
function updateGoalsFromProfile(){if(!state.autoGoals)return false;const calc=calculatePersonalGoals(state.profile);if(!calc)return false;for(const k of ['kcal','protein','fat','carbs','fiber','salt'])state.goals[k]=calc[k];return true}
function saveProfileForm(form){const d=new FormData(form);const p={...state.profile};for(const meta of PROFILE_FIELDS)p[meta[0]]=validProfileNumeric(d.get(meta[0]),meta);const target=d.get('targetWeight');p.targetWeight=target===''?null:Math.max(20,Math.min(350,Number(target)));
 p.birth=String(d.get('birth')||'');p.age=String(d.get('age')||'');p.sex=String(d.get('sex')||'unspecified');p.activity=String(d.get('activity')||'light');p.goal=String(d.get('goal')||'loss');p.deficit=Number(d.get('deficit'))||350;p.measuredAt=String(d.get('measuredAt')||dateStr());state.profile=p;state.autoGoals=d.has('autoGoals');captureMeasurement('manual');const applied=updateGoalsFromProfile();persist();render();toast(applied?'身体データと栄養目標を更新しました':'身体データを保存しました。推定目標には年齢・身長・体重・計算用区分が必要です。')}
function saveHealthReview(form){const d=new FormData(form);let updated=0;for(const meta of PROFILE_FIELDS){const raw=d.get(meta[0]);if(raw===null||String(raw).trim()==='')continue;state.profile[meta[0]]=validProfileNumeric(raw,meta);updated++;}if(d.get('birth')){state.profile.birth=String(d.get('birth'));updated++}if(d.get('age')!==''){state.profile.age=String(d.get('age'));updated++}if(['male','female'].includes(d.get('sex'))){state.profile.sex=String(d.get('sex'));updated++}if(!updated){toast('保存する数値がありません');return}state.profile.measuredAt=String(d.get('measuredAt')||dateStr());captureMeasurement('screen_capture');const applied=updateGoalsFromProfile();persist();closeModal();switchPage('profile');toast(`${updated}項目を登録${applied?'し、栄養目標を更新':''}しました`)}

function render(){document.body.classList.toggle('dark',state.theme==='dark');document.getElementById('topTitle').textContent=TITLES[state.page]||'今日の食事';document.getElementById('currentDateText').textContent=readable(state.date);document.querySelectorAll('#nav button,.mobile-nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===state.page);b.setAttribute('aria-current',b.dataset.page===state.page?'page':'false')});document.getElementById('app').innerHTML=({today,recommend:recommendation,catalog,insights,profile:profilePage,settings}[state.page]||today)()}
function switchPage(p){state.page=p;document.getElementById('sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'instant'});render()}
function recordCombo(items,meal,status='planned'){for(const f of items)state.logs.push(foodSnapshot(f,meal,status));persist();render();toast(`${MEAL_LABEL[meal]}に${items.length}商品を追加しました`)}
function addFoodModal(editId){const existing=editId?food(editId):null;let selected=existing?.store||'自炊・スーパー';document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="商品登録"><div class="modal-header"><h2>${existing?'商品を編集':'新しい商品を登録'}</h2><button class="icon-btn" data-action="closeModal">✕</button></div><form id="foodForm"><div class="fields"><div class="field span3"><label>商品・メニュー名 *</label><input name="name" required maxlength="100" value="${attr(existing?.name||'')}" placeholder="例：鮭おにぎり"></div><div class="field span2"><label>購入店舗 *</label><select name="store">${stores().map(s=>`<option value="${attr(s)}" ${s===selected?'selected':''}>${safe(s)}</option>`).join('')}</select></div><div class="field"><label>税込価格（円）</label><input name="price" type="number" min="0" max="100000" step="1" value="${existing?.price??''}" placeholder="未確認なら空欄"></div>${[['kcal','カロリー kcal'],['protein','たんぱく質 g'],['fat','脂質 g'],['carbs','炭水化物 g'],['salt','食塩相当量 g'],['fiber','食物繊維 g（不明は空欄）']].map(([key,label])=>`<div class="field"><label>${label}${key!=='fiber'?' *':''}</label><input name="${key}" type="number" ${key!=='fiber'?'required':''} min="0" max="10000" step="0.1" value="${existing?.[key]??''}" placeholder="${key==='fiber'?'任意':'必須'}"></div>`).join('')}<div class="field span3"><label>情報の出典URL（任意）</label><input name="source" type="url" value="${attr(existing?.source||'')}" placeholder="https://..."></div><div class="field span3"><label>注意書き（任意）</label><input name="note" maxlength="300" value="${attr(existing?.note||'')}" placeholder="包装表示などを基に記録"></div></div><div class="notice orange">ユーザー登録の栄養・価格情報は「自己登録／概算」として扱います。アレルギーを含む安全性の判定には使用しないでください。</div><div class="modal-footer">${existing?`<button type="button" class="btn btn-danger" data-action="deleteFood" data-id="${existing.id}">商品を削除</button>`:''}<button type="button" class="btn" data-action="closeModal">キャンセル</button><button type="submit" class="btn btn-primary">保存する</button></div></form></div></div>`;document.querySelector('#foodForm').dataset.edit=existing?.id||''}
function addEntryModal(id,meal=state.meal){let f=food(id);if(!f)return;document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-header"><h2>食事に追加</h2><button class="icon-btn" data-action="closeModal">✕</button></div><div class="notice"><b>${safe(f.name)}</b>${safe(f.store)} ・ ${fmt(f.kcal)} kcal / 1単位 ・ ${money(f.price)}</div><form id="entryForm" data-id="${f.id}"><div class="fields"><div class="field"><label>食事</label><select name="meal">${MEALS.map(m=>`<option value="${m}" ${meal===m?'selected':''}>${MEAL_LABEL[m]}</option>`).join('')}</select></div><div class="field"><label>数量</label><input type="number" name="qty" min="0.5" max="10" step="0.5" value="1"></div><div class="field"><label>状態</label><select name="status"><option value="planned">買う予定 / これから</option><option value="eaten">すでに食べた</option></select></div></div><div class="modal-footer"><button type="button" class="btn" data-action="closeModal">戻る</button><button class="btn btn-primary" type="submit">追加する</button></div></form></div></div>`}
function addStoreModal(){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-header"><h2>店舗を追加</h2><button class="icon-btn" data-action="closeModal">✕</button></div><form id="storeForm"><div class="field"><label>店舗名</label><input name="store" required maxlength="80" placeholder="例：近所の定食屋"></div><div class="modal-footer"><button type="button" class="btn" data-action="closeModal">キャンセル</button><button class="btn btn-primary" type="submit">追加する</button></div></form></div></div>`}
function closeModal(){document.querySelector('#modalRoot').innerHTML='';closePhoto()}
function autoDay(){const done=[];const oldstore=state.store;for(const m of ['breakfast','lunch','dinner']){if(entries().some(x=>x.meal===m))continue;const preferred=(m==='lunch'&&oldstore!=='all')?oldstore:'自炊・スーパー';let rec=candidates(state.date,m,preferred)[0];if(!rec && preferred!=='自炊・スーパー')rec=candidates(state.date,m,'自炊・スーパー')[0];if(!rec)continue;for(const f of rec.items)state.logs.push(foodSnapshot(f,m,'planned'));done.push(MEAL_LABEL[m]);}persist();render();toast(done.length?`${done.join('・')}を予定に追加しました`:'追加できる食事がありません（予算・条件をご確認ください）')}
function exportFile(name,type,content){let blob=new Blob([content],{type});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);a.remove()}
function exportJSON(){exportFile('nutripath-backup-'+dateStr()+'.json','application/json;charset=utf-8',JSON.stringify({format:'nutripath-v2',exportedAt:new Date().toISOString(),goals:state.goals,logs:state.logs,custom:state.custom,extraStores:state.extraStores,profile:state.profile,measurements:state.measurements,autoGoals:state.autoGoals,theme:state.theme},null,2))}
function exportCSV(){let keys=['date','meal','status','name','store','qty','kcal','protein','fat','carbs','fiber','salt','price'];let rows=[keys.map(escapeCsv).join(',')];for(let x of state.logs){rows.push(keys.map(k=>escapeCsv(x[k]??'')).join(','))}exportFile('nutripath-history-'+dateStr()+'.csv','text/csv;charset=utf-8','\uFEFF'+rows.join('\r\n'))}
function copyShopping(){let rows=entries().filter(x=>x.status==='planned');let t=rows.length?rows.map(x=>`${MEAL_LABEL[x.meal]} | ${x.store} | ${x.name} ×${x.qty} | ${money(x.price==null?null:x.price*x.qty)}`).join('\n'):'購入予定がありません';if(navigator.clipboard?.writeText){navigator.clipboard.writeText(t).then(()=>toast('購入リストをコピーしました')).catch(()=>toast('コピーできませんでした'))}else{toast('このブラウザではコピーできません。JSON保存をご利用ください')}}
function handleAction(b){const a=b.dataset.action,id=b.dataset.id;
switch(a){case 'prev':state.date=shift(state.date,-1);render();break;case 'next':state.date=shift(state.date,1);render();break;case 'todayDate':state.date=dateStr();render();break;case 'recommendMeal':state.meal=b.dataset.meal;switchPage('recommend');break;case 'pickMeal':state.meal=b.dataset.meal;switchPage('catalog');break;case 'autoDay':autoDay();break;case 'chooseReco':{let r=candidates(state.date,state.meal,state.store)[+b.dataset.idx];if(r)recordCombo(r.items,state.meal);break;}case 'addEntry':addEntryModal(id);break;case 'addFood':addFoodModal();break;case 'editFood':addFoodModal(id);break;case 'deleteFood':if(confirm('この商品を削除しますか？過去の食事記録は残ります。')){state.custom=state.custom.filter(x=>x.id!==id);persist();closeModal();render()}break;case 'addStore':addStoreModal();break;case 'closeModal':closeModal();break;case 'toggleEat':{let x=state.logs.find(y=>y.id===id);if(x)x.status=x.status==='eaten'?'planned':'eaten';persist();render();break;}case 'qtyUp':case 'qtyDown':{let x=state.logs.find(y=>y.id===id);if(x)x.qty=Math.max(.5,Math.min(10,x.qty+(a==='qtyUp'?.5:-.5)));persist();render();break;}case 'remove':state.logs=state.logs.filter(x=>x.id!==id);persist();render();break;case 'resetGoals':if(confirm('目標を初期値に戻しますか？')){state.goals={...DEFAULT_GOALS};persist();render()}break;case 'clearLogs':if(confirm('全ての食事記録を削除します。バックアップは作成しましたか？')){state.logs=[];persist();render();toast('食事記録を削除しました')}break;case 'exportJSON':exportJSON();break;case 'exportCSV':exportCSV();break;case 'copyShopping':copyShopping();break;case 'openHealthImport':openHealthImport();break;case 'readHealthImage':readHealthImage();break;case 'parseHealthText':applyOcrText();break;case 'deleteMeasurement':if(confirm('この測定履歴を削除しますか？')){state.measurements=state.measurements.filter(x=>x.id!==id);persist();render()}break;case 'clearProfile':if(confirm('身体データと測定履歴をすべて削除しますか？食事記録は残ります。')){state.profile={...PROFILE_DEFAULT};state.measurements=[];state.autoGoals=false;persist();render();toast('身体データと測定履歴を削除しました')}break;default:break}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-page],[data-store]');if(!b){if(e.target.classList.contains('modal-backdrop'))closeModal();return;}if(b.dataset.action){e.preventDefault();handleAction(b);return;}if(b.dataset.page){e.preventDefault();switchPage(b.dataset.page);return;}if(b.dataset.store!==undefined){state.store=b.dataset.store;render()}});
document.addEventListener('input',e=>{if(e.target.id==='queryInput'){state.query=e.target.value;const pos=e.target.selectionStart;render();let node=document.querySelector('#queryInput');if(node){node.focus();node.setSelectionRange(pos,pos)}}});
document.addEventListener('change',e=>{if(e.target.id==='dayInput'){state.date=e.target.value||dateStr();render()}if(e.target.id==='mealSelect'){state.meal=e.target.value;render()}if(e.target.id==='sortInput'){state.sort=e.target.value;render()}if(e.target.id==='healthImageFile'){const f=e.target.files?.[0];if(!f)return;if(f.size>15*1024*1024){healthStatus('15MB以下の画像を選択してください',true);return}if(!f.type.startsWith('image/')){healthStatus('画像ファイルを選択してください',true);return}if(photoObjectURL)URL.revokeObjectURL(photoObjectURL);photoFile=f;photoObjectURL=URL.createObjectURL(f);const preview=document.getElementById('healthPreview');if(preview){preview.src=photoObjectURL;preview.classList.remove('hide')}readHealthImage()}if(e.target.id==='importFile'){const f=e.target.files?.[0];if(!f)return;let reader=new FileReader();reader.onload=()=>{try{let d=JSON.parse(reader.result);if(!['nutripath-v1','nutripath-v2'].includes(d.format)||!Array.isArray(d.logs)||!Array.isArray(d.custom))throw Error('形式が違います');if(d.logs.length>50000||d.custom.length>3000)throw Error('ファイルの件数が多すぎます');if(!confirm('既存データをバックアップの内容で置き換えますか？'))return;state.logs=d.logs;state.custom=d.custom;state.extraStores=Array.isArray(d.extraStores)?d.extraStores:[];state.goals={...DEFAULT_GOALS,...d.goals};state.theme=d.theme==='dark'?'dark':'light';state.profile={...PROFILE_DEFAULT,...(d.profile||{})};state.measurements=Array.isArray(d.measurements)?d.measurements.slice(-400):[];state.autoGoals=d.autoGoals??true;persist();render();toast('バックアップを読み込みました')}catch(err){alert('読み込みに失敗しました：'+err.message)}};reader.readAsText(f)}});
document.addEventListener('submit',e=>{const form=e.target;if(!['foodForm','storeForm','goalsForm','entryForm','profileForm','healthReviewForm'].includes(form.id))return;e.preventDefault();const data=new FormData(form);if(form.id==='profileForm'){try{saveProfileForm(form)}catch(err){toast(err.message)}return}if(form.id==='healthReviewForm'){try{saveHealthReview(form)}catch(err){toast(err.message)}return}if(form.id==='goalsForm'){let result={};for(const k in DEFAULT_GOALS){let v=Number(data.get(k));if(!Number.isFinite(v)||v<=0){toast('目標値は0より大きい数値で入力してください');return}result[k]=v}state.goals=result;state.autoGoals=false;persist();render();toast('目標を保存しました（個別設定）')}
if(form.id==='storeForm'){const n=String(data.get('store')||'').trim();if(!n||stores().includes(n)){toast('店舗名が空欄か、すでに登録済みです');return}state.extraStores.push(n);state.store=n;persist();closeModal();render();toast('店舗を追加しました')}
if(form.id==='foodForm'){let edit=form.dataset.edit;let f={id:edit||('u'+Date.now().toString(36)),store:String(data.get('store')),name:String(data.get('name')).trim(),kcal:Number(data.get('kcal')),protein:Number(data.get('protein')),fat:Number(data.get('fat')),carbs:Number(data.get('carbs')),salt:Number(data.get('salt')),fiber:data.get('fiber')===''?null:Number(data.get('fiber')),price:data.get('price')===''?null:Number(data.get('price')),source:String(data.get('source')||''),quality:'custom',note:String(data.get('note')||'ユーザー登録の値'),time:'any',kind:'food',price_type:'exact'};if(!f.name||!f.store){toast('商品名と店舗は必須です');return}if(!['kcal','protein','fat','carbs','salt'].every(k=>Number.isFinite(f[k])&&f[k]>=0)){toast('栄養値を確認してください');return}if(edit)state.custom=state.custom.map(x=>x.id===edit?f:x);else state.custom.push(f);persist();closeModal();render();toast('商品を保存しました')}
if(form.id==='entryForm'){const f=food(form.dataset.id);if(!f)return;const qty=Number(data.get('qty'));if(!Number.isFinite(qty)||qty<.5||qty>10){toast('数量が正しくありません');return}const row=foodSnapshot(f,String(data.get('meal')),String(data.get('status')));row.qty=qty;state.logs.push(row);persist();closeModal();render();toast('食事を記録しました')}});
document.getElementById('quickAddBtn').addEventListener('click',()=>addFoodModal());document.getElementById('mobileMenu').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));document.getElementById('themeToggle').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';persist();render()});
window.addEventListener('nutripath:data',e=>{
 const d=e.detail||{};
 state.goals={...DEFAULT_GOALS,...(d.goals||{})};
 state.profile={...PROFILE_DEFAULT,...(d.profile||{})};
 for(const k of ['logs','custom','extraStores','measurements'])state[k]=Array.isArray(d[k])?d[k]:[];
 state.autoGoals=d.autoGoals??true;state.theme=d.theme==='dark'?'dark':'light';
 closeModal();render();
});
render();
})();
